 static Point3d P(double[] p){Need(p!=null&&p.Length==3&&p.All(x=>!Double.IsNaN(x)&&!Double.IsInfinity(x)),"FINITE_3D_POINT_REQUIRED");return new Point3d(p[0],p[1],p[2]);}
