 static GripDataCollection Grips(Entity e){var g=AllGrips(e);Need(g.Count==4,"SINGLE_UPTEXT_LEADER_FOUR_GRIPS_REQUIRED");return g;}
 static bool MoveTo(Entity e,int index,Point3d target){var g=AllGrips(e);Need(index<g.Count,"GRIP_INDEX_CHANGED");var delta=target-g[index].GripPoint;if(delta.Length<=1e-8)return false;var one=new GripDataCollection();one.Add(g[index]);e.MoveGripPointsAt(one,delta,(MoveGripPointsFlags)0);return true;}
 static void Topology(Entity e){var g=Grips(e);var pieces=new DBObjectCollection();try{e.Explode(pieces);var lines=pieces.Cast<DBObject>().OfType<Line>().ToArray();Need(lines.Length==2,"SINGLE_BRANCH_NATIVE_LEADER_REQUIRED");Func<Line,Point3d,Point3d,bool> connects=(l,a,b)=>(l.StartPoint.DistanceTo(a)<1e-8&&l.EndPoint.DistanceTo(b)<1e-8)||(l.StartPoint.DistanceTo(b)<1e-8&&l.EndPoint.DistanceTo(a)<1e-8);Need(lines.Any(l=>connects(l,g[0].GripPoint,g[1].GripPoint))&&lines.Any(l=>connects(l,g[0].GripPoint,g[2].GripPoint)),"NATIVE_LEADER_GRIP_ROLE_MISMATCH");}finally{foreach(DBObject o in pieces)o.Dispose();}}
 static object Prop(Entity e,string n){var c=e.AcadObject;return c.GetType().InvokeMember(n,BindingFlags.GetProperty,null,c,null);}
