 static double AngleError(double a,double b){return Math.Abs((a-b+540)%360-180);}
 static void TextParts(Entity e,List<string> rows,int depth){Need(depth<8,"TEXT_EXPLODE_DEPTH");var text=e as DBText;if(text!=null){rows.Add(J.Serialize(new{text=text.TextString,height=text.Height,width=text.WidthFactor,style=text.TextStyleId.Handle.ToString()}));return;}if(e is Line||e is Polyline||e is Arc||e is Circle)return;var parts=new DBObjectCollection();try{e.Explode(parts);foreach(DBObject p in parts){var x=p as Entity;if(x!=null)TextParts(x,rows,depth+1);}}finally{foreach(DBObject p in parts)p.Dispose();}}
 static string TextFormat(Entity e){var rows=new List<string>();TextParts(e,rows,0);Need(rows.Count>0,"NATIVE_DISPLAY_TEXT_REQUIRED");return J.Serialize(rows);}
 static void CheckTemplate(Entity e,Item i){Need(e.GetRXClass().Name=="TDbSymbMultiLeader"&&i.expected!=null,"NATIVE_LEADER_EXPECTED_REQUIRED");Topology(e);var g=Grips(e);Need(i.expected.grips!=null&&i.expected.grips.Length==4,"EXPECTED_TEMPLATE_GRIPS");for(int k=0;k<4;k++)Need(g[k].GripPoint.DistanceTo(P(i.expected.grips[k]))<1e-8,"TEMPLATE_GRIP_CHANGED");Need((string)Prop(e,"UpText")==i.expected.up&&(string)Prop(e,"DownText")==i.expected.down&&i.expected.down==""&&(string)Prop(e,"Height")==i.expected.height&&Math.Abs(Convert.ToDouble(Prop(e,"Scale"))-i.expected.scale)<1e-10&&Math.Abs(Convert.ToDouble(Prop(e,"LayoutRotation"))-i.expected.rotation)<1e-8,"TEMPLATE_PROPERTIES_CHANGED");}
 static string Shape(Database db,string[] handles){var previous=HostApplicationServices.WorkingDatabase;try{HostApplicationServices.WorkingDatabase=db;return ShapeCore(db,handles);}finally{HostApplicationServices.WorkingDatabase=previous;}}
 static string ShapeCore(Database db,string[] handles){var rows=new List<object>();using(var tr=db.TransactionManager.StartTransaction())foreach(var h in handles){var e=(Entity)tr.GetObject(db.GetObjectId(false,new Handle(Convert.ToInt64(h,16)),0),OpenMode.ForRead);var g=AllGrips(e);rows.Add(new{up=Prop(e,"UpText"),down=Prop(e,"DownText"),height=Prop(e,"Height"),scale=Prop(e,"Scale"),rotation=Prop(e,"LayoutRotation"),handle=e.Handle.ToString(),owner=e.OwnerId.Handle.ToString(),type=e.GetRXClass().Name,layer=e.Layer,color=e.Color.ToString(),linetype=e.Linetype,lineweight=(int)e.LineWeight,grips=g.Cast<GripData>().Select(x=>new[]{x.GripPoint.X,x.GripPoint.Y,x.GripPoint.Z}).ToArray(),display=NativeDetailsReadV2.Piece(e,0)});}return J.Serialize(rows);}
 static void CheckUpdate(Entity e,Item i){
  Need(e.GetRXClass().Name=="TDbSymbMultiLeader"&&i.expected!=null,"NATIVE_LEADER_EXPECTED_REQUIRED");var g=AllGrips(e);
  Need((string)Prop(e,"UpText")==i.expected.up&&(string)Prop(e,"DownText")==i.expected.down,"TEMPLATE_TEXT_CHANGED");
  if(i.grips==null&&i.expected.grips==null){i.expected.grips=g.Cast<GripData>().Select(x=>new[]{x.GripPoint.X,x.GripPoint.Y,x.GripPoint.Z}).ToArray();i.expected.height=(string)Prop(e,"Height");if(!i.scale.HasValue)i.expected.scale=Convert.ToDouble(Prop(e,"Scale"));i.expected.rotation=Convert.ToDouble(Prop(e,"LayoutRotation"));}
Need(g.Count>=3&&i.expected.grips!=null&&g.Count==i.expected.grips.Length,"EXPECTED_LEADER_GRIPS");for(int k=0;k<g.Count;k++)Need(g[k].GripPoint.DistanceTo(P(i.expected.grips[k]))<1e-8,"TEMPLATE_GRIP_CHANGED");
  Need((string)Prop(e,"UpText")==i.expected.up&&(string)Prop(e,"DownText")==i.expected.down&&(string)Prop(e,"Height")==i.expected.height&&Math.Abs(Convert.ToDouble(Prop(e,"Scale"))-i.expected.scale)<1e-10&&Math.Abs(Convert.ToDouble(Prop(e,"LayoutRotation"))-i.expected.rotation)<1e-8,"TEMPLATE_PROPERTIES_CHANGED");
