 static ObjectId UpdateOwner(Database db,Transaction tr,string layout){
  if(String.IsNullOrEmpty(layout)||layout=="Model")return SymbolUtilityServices.GetBlockModelSpaceId(db);
  var layouts=(DBDictionary)tr.GetObject(db.LayoutDictionaryId,OpenMode.ForRead);Need(layouts.Contains(layout),"NAMED_PAPER_LAYOUT_REQUIRED");
  var row=(Layout)tr.GetObject(layouts.GetAt(layout),OpenMode.ForRead);Need(!row.ModelType,"PAPER_LAYOUT_REQUIRED");return row.BlockTableRecordId;
 }
 static string[] Update(Document doc,Job job,Action mutate){
  Need(job.items!=null&&job.items.Length>0&&job.items.Select(i=>i.template_handle.ToUpperInvariant()).Distinct().Count()==job.items.Length,"UNIQUE_UPDATE_TARGETS_REQUIRED");var db=doc.Database;var selected=new HashSet<string>(job.items.Select(i=>i.template_handle),StringComparer.OrdinalIgnoreCase);var touched=new HashSet<string>();
  ObjectEventHandler modified=(sender,e)=>{if(e.DBObject is Entity&&!selected.Contains(e.DBObject.Handle.ToString()))touched.Add(e.DBObject.Handle.ToString());};
  ObjectErasedEventHandler erased=(sender,e)=>{if(e.Erased&&e.DBObject is Entity)touched.Add(e.DBObject.Handle.ToString());};
  using(var tr=db.TransactionManager.StartTransaction()){
   foreach(var i in job.items){var e=(Entity)tr.GetObject(db.GetObjectId(false,new Handle(Convert.ToInt64(i.template_handle,16)),0),OpenMode.ForRead);Need(e.OwnerId==UpdateOwner(db,tr,i.layout)&&e.Layer==i.layer,"EXACT_LAYOUT_TARGET_LAYER_CHANGED");CheckUpdate(e,i);Need(i.text_grip==null,"TEXT_GRIP_NOT_TRANSLATION_USE_LEDGE_CONTROL");if(i.rotation.HasValue){Need(job.items.Length==1&&i.grips!=null&&!i.scale.HasValue&&i.up_text==null&&i.down_text==null&&!Double.IsNaN(i.rotation.Value)&&!Double.IsInfinity(i.rotation.Value)&&Math.Abs(i.rotation.Value)<=360,"ROTATION_SINGLE_GEOMETRY_ONLY");}Need(i.grips!=null||i.up_text!=null||i.down_text!=null||i.scale.HasValue,"UPDATE_ACTION_REQUIRED");if(i.scale.HasValue)Need(i.scale.Value>0&&!Double.IsInfinity(i.scale.Value)&&i.expected.scale>0,"POSITIVE_SCALE_AND_EXPECTED_SCALE_REQUIRED");if(i.grips!=null){CheckTemplate(e,i);Need(i.grips.Length==3&&(i.down_text==null||i.down_text==""),"SINGLE_UPTEXT_MOVE_REQUIRED");var u=P(i.grips[1])-P(i.grips[0]);var v=P(i.grips[2])-P(i.grips[0]);Need(u.Length>1e-6&&v.Length>1e-6&&Math.Abs(u.DotProduct(v)/(u.Length*v.Length))<1e-7,"ORTHOGONAL_LEADER_REQUIRED");}}
   db.ObjectModified+=modified;db.ObjectAppended+=modified;db.ObjectErased+=erased;
   try{mutate();foreach(var i in job.items){var e=(Entity)tr.GetObject(db.GetObjectId(false,new Handle(Convert.ToInt64(i.template_handle,16)),0),OpenMode.ForWrite);string textFormat=i.rotation.HasValue?TextFormat(e):null;string style=J.Serialize(new{owner=e.OwnerId.Handle.ToString(),layer=e.Layer,color=e.Color.ToString(),lt=e.Linetype,lw=(int)e.LineWeight});
    if(i.rotation.HasValue)Put(e,"LayoutRotation",(i.rotation.Value%360+360)%360);
    if(i.up_text!=null)Put(e,"UpText",i.up_text);if(i.down_text!=null)Put(e,"DownText",i.down_text);if(i.scale.HasValue)Put(e,"Scale",i.scale.Value);
    if(i.grips!=null||i.scale.HasValue){var targets=i.grips??i.expected.grips;for(int k=0;k<3;k++){MoveTo(e,k,P(targets[k]));}}
    e.RecordGraphicsModified(true);if(i.grips!=null)Topology(e);var actual=AllGrips(e);Need(actual.Count>=3,"NATIVE_LEADER_GEOMETRY_MISSING");var target=i.grips??i.expected.grips;for(int k=0;k<3;k++)Need(actual[k].GripPoint.DistanceTo(P(target[k]))<1e-8,"UPDATE_GRIP_MISMATCH");
    Need((string)Prop(e,"UpText")== (i.up_text??i.expected.up)&&(string)Prop(e,"DownText")== (i.down_text??i.expected.down)&&(string)Prop(e,"Height")==i.expected.height&&Math.Abs(Convert.ToDouble(Prop(e,"Scale"))-(i.scale??i.expected.scale))<1e-10&&AngleError(Convert.ToDouble(Prop(e,"LayoutRotation")),i.rotation??i.expected.rotation)<1e-8,"UPDATE_TEXT_STYLE_CHANGED");if(i.rotation.HasValue)Need(textFormat==TextFormat(e),"ROTATION_DISPLAY_TEXT_FORMAT_CHANGED");Need(style==J.Serialize(new{owner=e.OwnerId.Handle.ToString(),layer=e.Layer,color=e.Color.ToString(),lt=e.Linetype,lw=(int)e.LineWeight}),"UPDATE_ENTITY_STYLE_CHANGED");}
    Need(touched.Count==0,"UNSELECTED_ENTITY_TOUCHED:"+String.Join(",",touched));tr.Commit();Need(touched.Count==0,"UNSELECTED_ENTITY_TOUCHED_ON_COMMIT:"+String.Join(",",touched));}
   finally{db.ObjectModified-=modified;db.ObjectAppended-=modified;db.ObjectErased-=erased;}
  }return job.items.Select(i=>i.template_handle).ToArray();
 }
 public static string[] Apply(Document doc,Job job,Action mutate){if(job.update_existing)return Update(doc,job,mutate);Need(job.items!=null&&job.items.Length>0,"ITEMS_REQUIRED");var db=doc.Database;var result=new List<string>();using(var tr=db.TransactionManager.StartTransaction()){var ms=(BlockTableRecord)tr.GetObject(SymbolUtilityServices.GetBlockModelSpaceId(db),OpenMode.ForRead);var lt=(LayerTable)tr.GetObject(db.LayerTableId,OpenMode.ForRead);
  foreach(var i in job.items){Need(i.grips!=null&&i.grips.Length==3&&lt.Has(i.layer)&&!String.IsNullOrWhiteSpace(i.up_text),"THREE_TARGET_GRIPS_TEXT_LAYER_REQUIRED");var e=(Entity)tr.GetObject(db.GetObjectId(false,new Handle(Convert.ToInt64(i.template_handle,16)),0),OpenMode.ForRead);Need(e.OwnerId==ms.ObjectId,"MODEL_TEMPLATE_REQUIRED");CheckTemplate(e,i);var u=P(i.grips[1])-P(i.grips[0]);var v=P(i.grips[2])-P(i.grips[0]);Need(u.Length>1e-6&&v.Length>1e-6&&Math.Abs(u.DotProduct(v)/(u.Length*v.Length))<1e-7,"ORTHOGONAL_LEADER_REQUIRED");}
  mutate();ms.UpgradeOpen();foreach(var i in job.items){var id=db.GetObjectId(false,new Handle(Convert.ToInt64(i.template_handle,16)),0);var map=new IdMapping();db.DeepCloneObjects(new ObjectIdCollection(new[]{id}),ms.ObjectId,map,false);var e=(Entity)tr.GetObject(map[id].Value,OpenMode.ForWrite);e.LayerId=lt[i.layer];Put(e,"UpText",i.up_text);for(int k=0;k<3;k++){MoveTo(e,k,P(i.grips[k]));}e.RecordGraphicsModified(true);Topology(e);var actual=Grips(e);for(int k=0;k<3;k++)Need(actual[k].GripPoint.DistanceTo(P(i.grips[k]))<1e-8,"LEADER_GRIP_MISMATCH");Need((string)Prop(e,"UpText")==i.up_text&&(string)Prop(e,"DownText")==""&&(string)Prop(e,"Height")==i.expected.height&&Math.Abs(Convert.ToDouble(Prop(e,"Scale"))-i.expected.scale)<1e-10&&Math.Abs(Convert.ToDouble(Prop(e,"LayoutRotation"))-i.expected.rotation)<1e-8,"LEADER_STYLE_OR_TEXT_CHANGED");result.Add(e.Handle.ToString());}tr.Commit();}return result.ToArray();}
 static string Read(Document d,string[] h){return J.Serialize(NativeDetailsReadV2.Read(d,h));}
 [CommandMethod("HLCADGROUNDCOVERTESTV9",CommandFlags.Session)]public void Test(){
  var original=App.DocumentManager.MdiActiveDocument;var previous=HostApplicationServices.WorkingDatabase;var a=original.Editor.GetString(new PromptStringOptions("\nIsolated coordinate job: "){AllowSpaces=true});if(a.Status!=PromptStatus.OK)return;Job job=null;Document staging=null;
  try{job=J.Deserialize<Job>(File.ReadAllText(a.StringResult.Trim('"')));Need(NativeGeometryReadV1.Hash(job.input)==job.input_sha256&&!File.Exists(job.output)&&!File.Exists(job.receipt),"INPUT_OUTPUT_IDENTITY");string copy=job.output+".staging.dwg";File.Copy(job.input,copy,false);staging=App.DocumentManager.Open(copy,false);App.DocumentManager.MdiActiveDocument=staging;HostApplicationServices.WorkingDatabase=staging.Database;var templates=job.items.Select(i=>i.template_handle).Distinct().ToArray();string before,expected;string[] created;
   using(staging.LockDocument()){before=Read(staging,templates);created=Apply(staging,job,()=>{});staging.Editor.Regen();if(!job.update_existing)Need(CadValueCompareV1.Json(before,Read(staging,templates)),"TEMPLATE_CHANGED");expected=Read(staging,created);staging.Database.SaveAs(job.output,DwgVersion.AC1032);}
   App.DocumentManager.MdiActiveDocument=original;HostApplicationServices.WorkingDatabase=previous;staging.CloseAndDiscard();staging=App.DocumentManager.Open(job.output,true);App.DocumentManager.MdiActiveDocument=staging;HostApplicationServices.WorkingDatabase=staging.Database;string actual;
   using(staging.LockDocument()){actual=Read(staging,created);if(!job.update_existing)Need(CadValueCompareV1.Json(before,Read(staging,templates)),"REOPEN_TEMPLATE_CHANGED");Need(CadValueCompareV1.Json(expected,actual),"REOPEN_COORD_CHANGED");}
   Write(job.receipt,new{status="ISOLATED_NATIVE_GROUNDCOVER_VERIFIED",output=job.output,sha256=NativeGeometryReadV1.Hash(job.output),source_unchanged=NativeGeometryReadV1.Hash(job.input)==job.input_sha256,template_unchanged=!job.update_existing,updated_in_place=job.update_existing,unselected_entity_write_guard=job.update_existing,native_save_reopen_verified=true,created=job.update_existing?new string[0]:created,updated=job.update_existing?created:new string[0],entities=J.DeserializeObject(actual)});
  }catch(System.Exception e){if(job!=null&&!File.Exists(job.receipt))Write(job.receipt,new{status="GROUNDCOVER_TEST_FAILED",error=e.ToString()});}
  finally{App.DocumentManager.MdiActiveDocument=original;HostApplicationServices.WorkingDatabase=previous;if(staging!=null)staging.CloseAndDiscard();}
 }
 [CommandMethod("HLCADGROUNDCOVERV3",CommandFlags.Session)]public void Run(){RunBound("groundcover_create");}
