 void RunBound(string kind){
  var a=App.DocumentManager.MdiActiveDocument.Editor.GetString(new PromptStringOptions("\nCoordinate manifest: "){AllowSpaces=true});if(a.Status!=PromptStatus.OK)return;Type adapter=null;Job job=null;bool owned=false,started=false,committed=false;
  try{var m=J.Deserialize<Manifest>(File.ReadAllText(a.StringResult.Trim('"')));var p=System.Diagnostics.Process.GetCurrentProcess();Need(p.Id==m.host.pid&&p.StartTime.ToUniversalTime().ToFileTimeUtc()==m.host.created&&Eq(p.MainModule.FileName,m.host.image),"HOST_IDENTITY");adapter=AppDomain.CurrentDomain.GetAssemblies().Select(x=>x.GetType("V736BaseSession",false)).Single(x=>x!=null);CadAdapterContractV1.Check(adapter);Need(Eq(adapter.Assembly.Location,m.loaded_dll)&&NativeGeometryReadV1.Hash(m.loaded_dll)==m.loaded_dll_sha256&&Eq((string)Get(adapter,"dir"),m.session_dir),"ADAPTER_IDENTITY");Need(!(bool)Get(adapter,"busy")&&!(bool)Get(adapter,"blocked")&&!File.Exists(Path.Combine(m.session_dir,"request.json")),"SESSION_BUSY");Need(Eq(Path.GetDirectoryName(m.request),m.session_dir)&&NativeGeometryReadV1.Hash(m.request)==m.request_sha256,"REQUEST_IDENTITY");var req=J.Deserialize<Request>(File.ReadAllText(m.request));Need(req.kind==kind&&NativeGeometryReadV1.Hash(req.job_path)==req.job_sha256,"JOB_IDENTITY");Call(adapter,"CheckPath",req.job_path);job=J.Deserialize<Job>(File.ReadAllText(req.job_path));job.update_existing=kind=="groundcover_update";Call(adapter,"CheckLive",job.input,job.input_sha256);Call(adapter,"CheckOutput",job.output,job.receipt);var doc=(Document)Get(adapter,"doc");Need(doc==App.DocumentManager.MdiActiveDocument,"ACTIVE_DOCUMENT_CHANGED");adapter.GetField("busy",F).SetValue(null,true);owned=true;
   using(doc.LockDocument()){var templates=job.items.Select(i=>i.template_handle).Distinct().ToArray();string before=Read(doc,templates);var created=Apply(doc,job,()=>started=true);committed=true;doc.Editor.Regen();if(!job.update_existing)Need(CadValueCompareV1.Json(before,Read(doc,templates)),"TEMPLATE_CHANGED");var rows=NativeDetailsReadV2.Read(doc,created);string expected=Shape(doc.Database,created);doc.Database.SaveAs(job.output,DwgVersion.AC1032);if(job.update_existing)using(var saved=new Database(false,true)){saved.ReadDwgFile(job.output,FileOpenMode.OpenForReadAndAllShare,true,"");saved.CloseInput(true);Need(CadValueCompareV1.Json(expected,Shape(saved,created)),"UPDATE_SAVE_REOPEN_MISMATCH");}string path=Path.GetFullPath(job.output),sha=NativeGeometryReadV1.Hash(path);((Dictionary<string,string>)Get(adapter,"approved"))[path]=sha;adapter.GetField("currentPath",F).SetValue(null,path);adapter.GetField("currentHash",F).SetValue(null,sha);Write(job.receipt,new{status="SAVED_STILL_OPEN",output=path,sha256=sha,pid=p.Id,changes=new{operation=kind,created=job.update_existing?new string[0]:created,updated=job.update_existing?created:new string[0],template_unchanged=!job.update_existing,text_style_preserved=true,unselected_entity_write_guard=job.update_existing,native_save_reopen_verified=job.update_existing,entities=rows}});Call(adapter,"State");}
  }catch(System.Exception e){string emergency=null;if(started&&adapter!=null){adapter.GetField("blocked",F).SetValue(null,true);try{var doc=(Document)Get(adapter,"doc");emergency=Path.Combine((string)Get(adapter,"dir"),"groundcover_emergency_"+Guid.NewGuid().ToString("N")+".dwg");using(doc.LockDocument())doc.Database.SaveAs(emergency,DwgVersion.AC1032);}catch{}}
   if(job!=null&&!File.Exists(job.receipt))Write(job.receipt,new{status=started?"BOUND_MODULE_FAILED":"REJECTED_BEFORE_WRITE",source_sha256=job.input_sha256,write_started=started,committed=committed,replayed=false,emergency=emergency,error=e.ToString()});
  }finally{if(owned)adapter.GetField("busy",F).SetValue(null,false);}
 }
